/// RHINO_COMPUTE_URLS: the list of URLs that compute will listen on.
/// </summary>
public static string[] Urls { get; set; }

public static string CreateCacheKey(string input)
{
    // Use input string to calculate MD5 hash
    using (System.Security.Cryptography.MD5 md5 = System.Security.Cryptography.MD5.Create())
    {
        byte[] inputBytes = System.Text.Encoding.ASCII.GetBytes(input);
        byte[] hashBytes = md5.ComputeHash(inputBytes);

        // Convert the byte array to hexadecimal string
        var sb = new System.Text.StringBuilder("md5_");
        for (int i = 0; i < hashBytes.Length; i++)
        {
            sb.Append(hashBytes[i].ToString("X2"));
        }
        return sb.ToString();
    }
}

public static GrasshopperDefinition GetCachedDefinition(string key)
{
    if (string.IsNullOrWhiteSpace(key))
        return null;
    var def = definitionCache.Get(key) as CachedDefinition;
    if (def == null)
    {
        string filename = DefinitionCacheFileName(key);
        if (filename != null && System.IO.File.Exists(filename))
        {
            try
            {
                string data = System.IO.File.ReadAllText(filename);
                return GrasshopperDefinition.FromBase64String(data, true);
            }
            catch(Exception ex)
            {
                Log.Error($"Unable to read cache file: {filename}");
                Log.Error(ex, "File error exception");
            }
        }
        return null;
    }
    if (def.Definition.IsLocalFileDefinition)
    {
        if(def.WatchedFileRuntimeSerialNumber != GrasshopperDefinition.WatchedFileRuntimeSerialNumber)
        {
            definitionCache.Remove(key);
            return null;
        }
    }
    return def.Definition;
}

public static object GetCachedItem(JToken token, Type objectType, JsonSerializer serializer)
{
    string jsonString = token.ToString();
    if (jsonString.StartsWith("{") &&
        jsonString.EndsWith("}") &&
        jsonString.IndexOf("url", StringComparison.OrdinalIgnoreCase)>0 &&
        jsonString.IndexOf("http", StringComparison.OrdinalIgnoreCase)>0)
    {
        Dictionary<string, string> cacheDictionary = new Dictionary<string, string>();
        cacheDictionary = token.ToObject(cacheDictionary.GetType()) as Dictionary<string, string>;
        string url;
        if (cacheDictionary == null || !cacheDictionary.TryGetValue("url", out url))
            return null;

        JToken jtoken = null;
        string key = $"url:{url.ToLower()}";
        Tuple<JToken, object> cacheEntry = resultsCache.Get(key) as Tuple<JToken, object>;
        if( cacheEntry!=null)
        {
            Rhino.Geometry.GeometryBase geometry = cacheEntry.Item2 as Rhino.Geometry.GeometryBase;
            if (geometry != null)
                return geometry.DuplicateShallow();
            jtoken = cacheEntry.Item1;
        }
        if (jtoken == null)
        {
            // UrlGuard adds scheme validation, optional private-IP blocking,
            // and a Config.MaxRequestSize cap to the outbound fetch.
            string cacheString = UrlGuard.GetStringAsync(url, Config.MaxRequestSize).Result;
            object data = string.IsNullOrWhiteSpace(cacheString) ? null : Newtonsoft.Json.JsonConvert.DeserializeObject(cacheString);
            // Expect the URL to return a non-empty JSON array. Throw a descriptive
            // error instead of a bare NullReferenceException/IndexOutOfRange when the
            // fetched content is the wrong shape (this is an external-data boundary).
            if (!(data is Newtonsoft.Json.Linq.JArray ja) || ja.Count == 0)
                throw new InvalidOperationException($"Expected URL '{url}' to return a non-empty JSON array.");
            jtoken = ja[0];
        }

        if( jtoken!=null )
        {
            object rc = null;
            if (serializer == null)
                rc = jtoken.ToObject(objectType);
            else
                rc = jtoken.ToObject(objectType, serializer);

            cacheEntry = new Tuple<JToken, object>(jtoken, rc);
            resultsCache.Add(key, cacheEntry, CachePolicy);
            Rhino.Geometry.GeometryBase geometry = rc as Rhino.Geometry.GeometryBase;
            if (geometry != null)
                return geometry.DuplicateShallow();
            return rc;
        }
    }
    return null;
}

public static string GetCachedSolveResults(string key)
{
    if (string.IsNullOrWhiteSpace(key))
        return null;
    var cache = resultsCache.Get(key) as CachedResults;
    if (cache == null)
        return null;

    if (cache.Definition.IsLocalFileDefinition)
    {
        if (cache.WatchedFileRuntimeSerialNumber != GrasshopperDefinition.WatchedFileRuntimeSerialNumber)
        {
            resultsCache.Remove(key);
            return null;
        }
    }

    return cache.Json;
}

// Only a definition this process has already loaded; unlike GetCachedDefinition, never reads the cache directory.
public static GrasshopperDefinition GetLoadedDefinition(string key)
{
    if (string.IsNullOrWhiteSpace(key))
        return null;
    return (definitionCache.Get(key) as CachedDefinition)?.Definition;
}

/// <summary>
/// Purges every entry from the solve-results / URL-data cache. Does NOT touch the
/// definition cache, since active clients may hold Pointer references to entries
/// there. Returns the number of items removed. Exposed via the POST /cache/purge
/// endpoint for operator-driven cleanup when host memory pressure is observed.
/// </summary>
public static long PurgeSolveResults()
{
    return resultsCache.Trim(100);
}

public static void SetCachedDefinition(string key, GrasshopperDefinition definition, string data)
{
    CachedDefinition cachedef = new CachedDefinition
    {
        Definition = definition,
        WatchedFileRuntimeSerialNumber = GrasshopperDefinition.WatchedFileRuntimeSerialNumber
    };
    // Setting the cached instance again would retire it.
    if (!ReferenceEquals((definitionCache.Get(key) as CachedDefinition)?.Definition, definition))
        definitionCache.Set(key, cachedef, DefinitionPolicy);

    if (!string.IsNullOrWhiteSpace(data))
    {
        string filename = DefinitionCacheFileName(key);
        if (filename != null && !System.IO.File.Exists(filename))
        {
            try
            {
                if (!System.IO.Directory.Exists(DefinitionCacheDirectory))
                    System.IO.Directory.CreateDirectory(DefinitionCacheDirectory);

                System.IO.File.WriteAllText(filename, data);
                System.Threading.Tasks.Task.Run(() => DataCache.CGCacheDirectory());
            }
            catch(Exception ex)
            {
                Log.Error($"Unable to write cache file: {filename}");
                Log.Error(ex, "File error exception");
            }
        }
    }
}

public static void SetCachedSolveResults(string key, string jsonResults, GrasshopperDefinition definition)
{
    if (string.IsNullOrWhiteSpace(key))
        return;

    var cache = new CachedResults
    {
        Definition = definition,
        WatchedFileRuntimeSerialNumber = GrasshopperDefinition.WatchedFileRuntimeSerialNumber,
        Json = jsonResults
    };

    resultsCache.Add(key, cache, CachePolicy);
}

public static void MapEndpoints(IEndpointRouteBuilder app)
{
    app.MapGet("", HomePage);
    app.MapGet("version", GetVersion);
    app.MapGet("servertime", ServerTime);
    app.MapGet("plugins/rhino/installed", GetInstalledPluginsRhino);
    app.MapGet("plugins/gh/installed", GetInstalledPluginsGrasshopper);
    app.MapPost("cache/purge", PurgeCache);
    app.MapPost("shutdown", ShutdownChild);
}

public static class FixedEndPointsModule
{
    public static void MapEndpoints(IEndpointRouteBuilder app)
    {
        app.MapGet("", HomePage);
        app.MapGet("version", GetVersion);
        app.MapGet("servertime", ServerTime);
        app.MapGet("plugins/rhino/installed", GetInstalledPluginsRhino);
        app.MapGet("plugins/gh/installed", GetInstalledPluginsGrasshopper);
        app.MapPost("cache/purge", PurgeCache);
        app.MapPost("shutdown", ShutdownChild);
    }

    static void HomePage(HttpContext context)
    {
        context.Response.Redirect("https://www.rhino3d.com/compute");
    }

    static async Task GetVersion(HttpContext ctx)
    {
        var values = new Dictionary<string, string>
        {
            { "rhino", Rhino.RhinoApp.Version.ToString() },
            { "compute", Assembly.GetExecutingAssembly().GetName().Version.ToString() }
        };
        string git_sha = null; // appveyor will replace this
        values.Add("git_sha", git_sha);

        ctx.Response.ContentType= "application/json";
        await ctx.Response.WriteAsJsonAsync(values);
    }

    static async Task ServerTime(HttpContext ctx)
    {
        ctx.Response.ContentType = "application/json";
        await ctx.Response.WriteAsJsonAsync(DateTime.UtcNow);
    }

    static async Task GetInstalledPluginsRhino(HttpContext ctx)
    {
        var rhPluginInfo = new SortedDictionary<string, string>();
        foreach (var k in Rhino.PlugIns.PlugIn.GetInstalledPlugIns().Keys)
        {
            var info = Rhino.PlugIns.PlugIn.GetPlugInInfo(k);
            //Could also use: info.IsLoaded
            if (info != null && !rhPluginInfo.ContainsKey(info.Name) && !info.ShipsWithRhino)
            {
                rhPluginInfo.Add(info.Name, info.Version);
            }
        }

        ctx.Response.ContentType = "application/json";
        await ctx.Response.WriteAsJsonAsync(rhPluginInfo);
    }

    // POST /cache/purge — wipes the solve-results / URL-data cache. Does NOT touch
    // the definition cache, since active clients may hold Pointer references to
    // entries there and a purge would cause subsequent /grasshopper calls with those
    // pointers to fail. Operators expecting memory relief without breaking pointer-
    // based flows should use this endpoint. Auth-gated by ApiKeyMiddleware (POST
    // method requires the RhinoComputeKey header when Config.ApiKey is set).
    static async Task PurgeCache(HttpContext ctx)
    {
        long removed = DataCache.PurgeSolveResults();
        Serilog.Log.Information("Cache purge requested: removed {Count} solve-results / URL-data entries", removed);
        ctx.Response.ContentType = "application/json";
        await ctx.Response.WriteAsJsonAsync(new { purged = removed });
    }

    // POST /shutdown — graceful self-shutdown for this compute.geometry child. Auth-gated
    // by ApiKeyMiddleware (POST). Used by rhino.compute when its ApplicationStopping
    // lifecycle hook fires (clean parent exit), and by the planned /shutdown-children +
    // /recycle-children endpoints in rhino.compute for manual control. The existing
    // 5-second self-monitoring TimerTask in Shutdown.cs remains as the fallback for
    // hard-crash scenarios where the parent dies without running its lifecycle hooks.
    //
    // Responds 202 Accepted immediately and triggers app.StopAsync() on a background
    // task so the response can flush before the host stops.
    static Task ShutdownChild(HttpContext ctx)
    {
        Serilog.Log.Information("Received /shutdown request from {RemoteIp}", ctx.Connection.RemoteIpAddress);
        var lifetime = ctx.RequestServices.GetService<IHostApplicationLifetime>();
        ctx.Response.StatusCode = 202;
        _ = Task.Run(async () =>
        {
            await Task.Delay(50);  // let the response flush before stopping the host
            lifetime?.StopApplication();
        });
        return Task.CompletedTask;
    }

    static async Task GetInstalledPluginsGrasshopper(HttpContext ctx)
    {
        var ghPluginInfo = new SortedDictionary<string, string>();
        foreach (var obj in Grasshopper.Instances.ComponentServer.ObjectProxies.Where(o => o != null))
        {
            var asm = Grasshopper.Instances.ComponentServer.FindAssemblyByObject(obj.Guid);
            if (asm != null && !string.IsNullOrEmpty(asm.Name) && !asm.IsCoreLibrary && !ghPluginInfo.ContainsKey(asm.Name))
            {
                var version = (string.IsNullOrEmpty(asm.Version)) ? asm.Assembly.GetName().Version.ToString() : asm.Version;
                ghPluginInfo.Add(asm.Name, version);
            }
        }
        ctx.Response.ContentType = "application/json";
        await ctx.Response.WriteAsJsonAsync(ghPluginInfo);
    }
}

public override bool CanConvert(Type objectType)
{
    return objectType == typeof(Rhino.Collections.ArchivableDictionary);
}

protected DictHelper(SerializationInfo info, StreamingContext context)
{
    Type t = typeof(Rhino.Collections.ArchivableDictionary);
    var constructor = t.GetConstructor(System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance,
      null, new Type[] { typeof(SerializationInfo), typeof(StreamingContext) }, null);
    SerializedDictionary = constructor.Invoke(new object[] { info, context }) as Rhino.Collections.ArchivableDictionary;
}

public virtual void GetObjectData(SerializationInfo info, StreamingContext context)
{
    SerializedDictionary.GetObjectData(info, context);
}

public override object ReadJson(JsonReader reader, Type objectType, object existingValue, JsonSerializer serializer)
{
    string encoded = (string)reader.Value;
    var dh = JsonConvert.DeserializeObject<DictHelper>(encoded);
    return dh.SerializedDictionary;
}

public override void WriteJson(JsonWriter writer, object value, JsonSerializer serializer)
{
    string json = JsonConvert.SerializeObject(new DictHelper((Rhino.Collections.ArchivableDictionary)value));
    writer.WriteValue(json);
}

public static IEnumerable<GeometryEndPoint> AllEndPoints
{
    get
    {
        if(allEndPoints==null)
        {
            allEndPoints = new List<GeometryEndPoint>();
            foreach (string nameSpace in new string[] { "Rhino.Geometry", "Rhino.Geometry.Intersect" })
            {
                foreach (var endpoint in CreateEndpoints(typeof(Rhino.RhinoApp).Assembly, nameSpace))
                {
                    allEndPoints.Add(endpoint);
                }
            }

            var method = typeof(Rhino.Runtime.HostUtils).GetMethod("GetCustomComputeEndpoints");
            if( method!=null )
            {
                var customEndpoints = method.Invoke(null, null) as Tuple<string, Type>[];
                if( customEndpoints != null )
                {
                    foreach (var customEndpoint in customEndpoints)
                    {

                        foreach (var endpoint in GeometryEndPoint.Create(customEndpoint.Item2))
                        {
                            endpoint.UpdatePath(customEndpoint.Item1);
                            allEndPoints.Add(endpoint);
                        }
                    }
                }
            }
        }
        return allEndPoints;
    }
}

public static List<GeometryEndPoint> Create(Type t)
{
    List<GeometryEndPoint> endpoints = new List<GeometryEndPoint>();
    if (!t.IsAbstract)
    {
        var constructors = t.GetConstructors(BindingFlags.Instance | BindingFlags.Public);
        if (constructors != null && constructors.Length > 0)
        {
            GeometryEndPoint endpoint = new GeometryEndPoint(t, constructors);
            endpoints.Add(endpoint);
        }
    }

    var methods = t.GetMethods(BindingFlags.Public | BindingFlags.DeclaredOnly | BindingFlags.Instance | BindingFlags.Static);
    var methodlist = new List<MethodInfo>(methods);
    methodlist.Sort((a, b) => a.Name.CompareTo(b.Name));
    for (int i = 0; i < methodlist.Count; i++)
    {
        string funcname = methodlist[i].Name;
        var overloads = new List<MethodInfo>();
        overloads.Add(methodlist[i]);
        for (int j = i + 1; j < methodlist.Count; j++)
        {
            if (funcname.Equals(methodlist[j].Name))
            {
                i = j;
                overloads.Add(methodlist[i]);
                continue;
            }
            break;
        }

        if (overloads.Count > 1)
        {
            // This is the general "catch all" endpoint that attempts to figure out the best routine to call
            GeometryEndPoint endpoint = new GeometryEndPoint(t, overloads.ToArray());
            endpoints.Add(endpoint);
        }

        foreach (var overload in overloads)
        {
            // generate explicit endpoints for all overloads, even if there are no parameters (see #142)
            endpoints.Add(new GeometryEndPoint(t, overload));
        }
    }

    return endpoints;
}

protected GeometryEndPoint(string path, Type classType)
{
    Path = path;
    this.classType = classType;
}

public async Task Get(HttpContext context)
{
    string funcname = FunctionName();
    var sb = new System.Text.StringBuilder("<!DOCTYPE html><html><body>");
    sb.AppendLine($"<H1>{funcname}</H1>");
    sb.AppendLine("<p>");
    if (methods != null)
    {
        foreach (var method in methods)
        {
            var inParams = new List<Tuple<Type, string>>();
            var outParams = new List<Tuple<Type, string>>();
            {
                if (!method.IsStatic)
                    inParams.Add(new Tuple<Type, string>(classType, "self"));
                if (method.ReturnType != typeof(void))
                    outParams.Add(new Tuple<Type, string>(method.ReturnType, ""));
                foreach (var parameter in method.GetParameters())
                {
                    if (parameter.IsOut || parameter.ParameterType.IsByRef)
                        outParams.Add(new Tuple<Type, string>(parameter.ParameterType, parameter.Name));
                    if (!parameter.IsOut)
                        inParams.Add(new Tuple<Type, string>(parameter.ParameterType, parameter.Name));
                }
                if (!method.IsStatic)
                {
                    object[] methodAttrs = method.GetCustomAttributes(true);
                    if (methodAttrs != null)
                    {
                        bool isConst = false;
                        for (int i = 0; i < methodAttrs.Length; i++)
                        {
                            Attribute attr = methodAttrs[i] as Attribute;
                            if (attr != null && attr.ToString().Contains("ConstOperationAttribute"))
                            {
                                isConst = true;
                                break;
                            }
                        }
                        if (!isConst)
                            outParams.Add(new Tuple<Type, string>(classType, ""));
                    }
                }
            }

            if (outParams.Count > 1)
                sb.Append("[");
            for (int i = 0; i < outParams.Count; i++)
            {
                sb.Append($"{PrettyString(outParams[i].Item1)}");
                if (outParams[i].Item2 != "")
                    sb.Append($" {outParams[i].Item2}");
                if (i < (outParams.Count - 1))
                    sb.Append(", ");
            }
            sb.Append(outParams.Count > 1 ? "] " : " ");

            sb.Append($"{funcname}(");

            for (int i = 0; i < inParams.Count; i++)
            {
                sb.Append($"{PrettyString(inParams[i].Item1)} {inParams[i].Item2}");
                if (i < (inParams.Count - 1))
                    sb.Append(", ");
            }
            sb.AppendLine(")<br>");
        }
    }
    if (constructors != null)
    {
        foreach (var constructor in constructors)
        {
            sb.Append($"{classType.Name} {funcname}(");
            var parameters = constructor.GetParameters();
            for (int pi = 0; pi < parameters.Length; pi++)
            {
                sb.Append($"{PrettyString(parameters[pi].ParameterType)} {parameters[pi].Name}");
                if (pi < (parameters.Length - 1))
                    sb.Append(", ");
            }
            sb.AppendLine(")<br>");
        }
    }
    sb.AppendLine("</p></body></html>");
    await context.Response.WriteAsync(sb.ToString());
}

