public static int[] FromString(string path)
{
    string primer = path.Replace(" ", "").Replace("{", "").Replace("}", "");
    string[] stringValues = primer.Split(';');
    List<int> ints = new List<int>();
    foreach (string s in stringValues)
    {
        if (s != string.Empty)
        {
            ints.Add(Int32.Parse(s));
        }
    }
    return ints.ToArray();
}

