                        if (paramIndex >= 0 && outputRecipients.TryGetValue(name, out List<IGH_Param> rehookOutputs))
                        {
                            foreach (var rehookOutput in rehookOutputs)
                                rehookOutput.AddSource(Params.Output[paramIndex]); 
