    Log.Debug("  Timeout = {Timeout}", FormatTimeout(Config.ReverseProxyRequestTimeout));
    Log.Debug("  Child Startup Timeout = {ChildStartupTimeout}", FormatTimeout(Config.ChildStartupTimeout));
