computeFetch: function(endpoint, arglist, returnJson=true) {
    let request = {
      'method':'POST',
      'body': JSON.stringify(arglist),
      'headers': {'User-Agent': `compute.rhino3d.js/${RhinoCompute.version}`}
    }
    if (RhinoCompute.authToken) {
      request.headers['Authorization'] = RhinoCompute.authToken
    }
    if (RhinoCompute.apiKey) {
      request.headers['RhinoComputeKey'] = RhinoCompute.apiKey
    }

    let p = fetch(RhinoCompute.url+endpoint, request)
    if (returnJson) return p.then(r=>r.json())
    return p
  }

getAuthToken: function (useLocalStorage=true) {
    let auth = null
    if (useLocalStorage)
      auth = localStorage['compute_auth']
    if (auth == null) {
      auth = window.prompt('Rhino Accounts auth token\nVisit https://www.rhino3d.com/compute/login')
      if (auth != null && auth.length>20) {
        auth = 'Bearer ' + auth
        localStorage.setItem('compute_auth', auth)
      }
    }
    return auth
  }

zipArgs: function(multiple, ...args) {
    if (!multiple) return args

    if (args.length==1)
      return args[0].map(function(_,i) { return [args[0][i]] })
    if (args.length==2)
      return args[0].map(function(_,i) { return [args[0][i],args[1][i]] })
    if (args.length==3)
      return args[0].map(function(_,i) {
        return [args[0][i],args[1][i],args[2][i]] }
      )
    if (args.length==4)
      return args[0].map(function(_,i) {
        return [args[0][i],args[1][i],args[2][i],args[3][i]] }
      )
    if (args.length==5)
      return args[0].map(function(_,i) {
        return [args[0][i],args[1][i],args[2][i],args[3][i],args[4][i]] }
      )
    if (args.length==6)
      return args[0].map(function(_,i) {
        return [args[0][i],args[1][i],args[2][i],args[3][i],args[4][i],args[5][i]] }
      )
    if (args.length==7)
      return args[0].map(function(_,i) {
        return [args[0][i],args[1][i],args[2][i],args[3][i],args[4][i],args[5][i],args[6][i]] }
      )
    return args[0].map(function(_,i) {
      return [args[0][i],args[1][i],args[2][i],args[3][i],args[4][i],args[5][i],args[6][i],args[7][i]] }
    )
  }

class AnnotationBase extends GeometryBase {
		/**
		 * Type of annotation
		 */
		annotationType: AnnotationType;
		/**
		 * Id of this annotation's parent dimstyle
		 * If this annotation has overrides to dimstyle properties,
		 * those overrides will be represented in the DimensionStyle
		 * returned by DimensionStyle(ParentStyle)
		 */
		dimensionStyleId: string;
		/**
		 * Text including additional RTF formatting information
		 */
		richText: string;
		/**
		 * Text stripped of RTF formatting information
		 */
		plainText: string;
		/**
		 * Text stripped of RTF formatting information and with field expressions intact
		 */
		plainTextWithFields: string;
		/**
		 * Plane that this annotation lies on
		 */
		plane: Plane;
		/**
		 * Is text wrapping on
		 */
		textIsWrapped: boolean;
		/**
		 * True if this annotation has any per-object dimension style overrides
		 */
		hasPropertyOverrides: boolean;
		/**
		 * True if the annotation's text begins with an RTF header
		 */
		textHasRtfFormatting: boolean;
		/**
		 * Angle in radians between the text plane and the object plane
		 */
		textRotationRadians: number;
		/**
		 * Angle in degrees between the text plane and the object plane
		 */
		textRotationDegrees: number;
		/**
		 * @description Wrap text
		 * @returns {void}
		 */
		wrapText(): void;
		/**
		 * @description The effective dimension style for this annotation, combining the parent
		 * dimension style with any per-object overrides. Get the parent from
		 * File3dm.dimStyles.findId(annotation.dimensionStyleId).
		 * @returns {DimensionStyle}
		 */
		getDimensionStyle(parentDimStyle:DimensionStyle): DimensionStyle;
		/**
		 * @description Tests whether a specific dimension style field is overridden on this annotation
		 * @returns {boolean}
		 */
		isPropertyOverridden(field:DimensionStyleField): boolean;
		/**
		 * @description Clears all per-object dimension style overrides on this annotation
		 * @returns {void}
		 */
		clearPropertyOverrides(): void;
