		constructor(initialCapacity: number);
		/**
		 * @description Test a polyline to see if it is closed.
		 * @param {number} tolerance The tolerance.
		 * @returns {boolean} Returns true if polyline has 4 or more points, the distance between the
		start and end points is <= tolerance, and there is a
		point in the polyline whose distance from the start and end
		points is > tolerance.
		 */
